from collections import Counter

def one_bit_pairs(codes):
    count = Counter(codes)
    total = 0
    for code, k in count.items():
        for b in range(code.bit_length()):
            other = code ^ (1 << b)
            if other > code:
                total += k * count.get(other, 0)
    return total

def one_bit_pairs(codes):
    total = 0
    for i in range(len(codes)):
        for j in range(i + 1, len(codes)):
            x = codes[i] ^ codes[j]
            if x and x & (x - 1) == 0:
                total += 1
    return total
